class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        n = len(word)
        if n == 1:
            return 0

        operations = 0
        i = 0

        while i < n - 1:
            # Check if current and next characters are almost-equal
            if abs(ord(word[i]) - ord(word[i + 1])) <= 1:
                # We need to change one of them
                operations += 1
                # Skip the next character since we've handled this pair
                i += 2
            else:
                i += 1

        return operations
```

